tt=np.asarray(df['t'],float); PP=np.asarray(df['P'],float); yy=np.asarray(df['dP_dt'],float)
def F(p):
    return p[0]*np.tanh(p[1]*tt)+p[2]*np.tanh(p[3]*tt)*PP**3+p[4]*tt**p[5]*PP**p[6]+p[7]*tt**p[8]*PP**p[9]
def jac(p,h=1e-7):
    f0=F(p); J=np.zeros((len(tt),len(p)))
    for k in range(len(p)):
        q=p.copy(); q[k]+=h*max(1,abs(p[k])); J[:,k]=(F(q)-f0)/(h*max(1,abs(p[k])))
    return J
def LM(p):
    lam=1e-3
    for it in range(300):
        r=yy-F(p); J=jac(p)
        A=J.T@J; g=J.T@r
        step=np.linalg.solve(A+lam*np.diag(np.diag(A)+1e-9),g)
        pn=p+step
        if not np.all(np.isfinite(F(pn))): lam*=10; continue
        if np.sum((yy-F(pn))**2)<np.sum(r**2): p=pn; lam=max(lam/3,1e-12)
        else: lam*=5
        if lam>1e12: break
    return p, np.sum((yy-F(p))**2)/len(yy)/np.var(yy)
